import {items,sources,updates} from './evidence.mjs';
import {convert,presets,dietScenarios} from './model.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sourceLink=k=>`<a href="${sources[k].url}" target="_blank" rel="noopener">${esc(sources[k].title)}<span>${esc(sources[k].journal)}</span></a>`;
let filter='全部';
function page(name){if(!['explore','calculate','research','method'].includes(name))return;$$('.page').forEach(p=>p.hidden=p.id!==name);$$('.navigation button').forEach(n=>{n.classList.toggle('active',n.dataset.page===name);if(n.dataset.page===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});history.replaceState(null,'','#'+name);window.scrollTo({top:0,behavior:'instant'});}
$$('.navigation button').forEach(b=>b.onclick=()=>page(b.dataset.page));
$('#install').onclick=()=>$('#install-dialog').showModal();$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function renderCards(){const q=$('#search').value.trim().toLowerCase();const found=items.filter(i=>(filter==='全部'||i.category===filter)&&[i.title,i.category,i.desc,i.action,i.evidence].join(' ').toLowerCase().includes(q));$('#result-count').textContent=`${found.length} 项 · 不按“延寿分”排名`;$('#cards').innerHTML=found.length?found.map(i=>`<article class="card"><span class="tag ${i.category==='药物'?'amber':''}">${i.category} · ${i.date}</span><h3>${i.title}</h3><p>${i.desc}</p><div class="metric">${i.metric}</div><div class="metric-label">${i.label}</div><div class="card-actions"><span>${i.kind}</span><button data-item="${i.id}">证据与做法</button></div></article>`).join(''):'<div class="empty"><h3>还没有这个条目</h3><p>试试“肌酸”“米饭”“光”或清空筛选。缺少数据不等于没有效果。</p><button id="reset-search">显示全部</button></div>';$$('[data-item]').forEach(b=>b.onclick=()=>detail(b.dataset.item));if($('#reset-search'))$('#reset-search').onclick=()=>{filter='全部';$('#search').value='';syncFilters();renderCards()};}
function syncFilters(){$$('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))})}
$('#search').oninput=renderCards;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;syncFilters();renderCards()});
function detail(id){const i=items.find(x=>x.id===id);if(!i)throw Error('没有这个条目');$('#detail-content').innerHTML=`<span class="tag ${i.category==='药物'?'amber':''}">${i.category} · ${i.kind}</span><h2 style="margin-top:16px">${i.title}</h2><div class="metric">${i.metric}</div><p>${i.label}</p><h3>可以怎么做</h3><p>${i.action}</p><h3>研究发现了什么</h3><p>${i.evidence}</p><h3>适用人群与终点</h3><p>${i.population}</p><p>${i.endpoint}</p><div class="note ${i.category==='药物'?'warn':''}">${i.limit}</div>${i.preset?'<button id="try-preset">放入风险换算器</button>':''}${i.recipe?recipeHTML():''}<h3>原始来源</h3><div class="sources">${i.refs.map(sourceLink).join('')}</div><p class="small">核查日期 2026-10-07。证据类型是本站说明，未对每条做完整 GRADE 评级。</p>`;if(i.preset)$('#try-preset').onclick=()=>{$('#detail').close();page('calculate');applyPreset(i.preset)};if(i.recipe){$$('[data-recipe]').forEach(el=>el.oninput=recipeUpdate);recipeUpdate()}$('#detail').showModal();}
function recipeHTML(){return `<h3>把这一碗拆开看</h3><p class="small">下面是可改的示例配方，不是营养处方。输入实际用量，只做组成换算。</p><div class="form-grid">${[['fruit','完整水果',200],['yogurt','无糖酸奶',100],['nuts','原味坚果',10],['sugar','额外加入的纯糖',0]].map(([id,label,n])=>`<label class="field">${label} / 克<input data-recipe="${id}" type="number" min="0" max="2000" step="1" value="${n}"></label>`).join('')}</div><div id="recipe-result" class="recipe-output" aria-live="polite"></div>`;}
function recipeUpdate(){const v={};let valid=true;$$('[data-recipe]').forEach(el=>{v[el.dataset.recipe]=Number(el.value);if(el.value.trim()===''||!Number.isFinite(v[el.dataset.recipe])||v[el.dataset.recipe]<0||v[el.dataset.recipe]>2000)valid=false});if(!valid){$('#recipe-result').textContent='请填入 0–2,000 克的有效数值。';return}const total=Object.values(v).reduce((a,b)=>a+b,0);$('#recipe-result').innerHTML=total?`<b>总重 ${total.toFixed(0)} 克</b><p>完整水果占 ${(v.fruit/total*100).toFixed(0)}%；额外纯糖 ${v.sugar} 克，约贡献 ${Math.round(v.sugar*4)} 千卡。</p><p class="small">这里没有估算整碗热量；酸奶和水果自带糖不计入“额外纯糖”。若用糖浆或炼乳，应按标签折算其中的添加糖，不能把整份重量当纯糖。配方不能直接换成死亡率。</p>`:'请至少填写一种原料。';}
$('#calculate').innerHTML=`<p class="eyebrow">先问：降低的是哪一种风险？</p><h1>让数字回到尺度里。</h1><p class="lede">研究效应量 × 同一时间窗的基线。得到情景估计，不是你的寿命预测。</p><div class="columns"><div class="panel"><label class="field">选择一个例子<select id="preset">${Object.entries(presets).map(([id,p])=>`<option value="${id}">${p.label}</option>`).join('')}</select></label><label class="field">论文给出的效应量类型<select id="effect-type"><option value="HR">HR · 瞬时风险比</option><option value="RR">RR · 累计风险比</option><option value="RATE">Rate ratio · 每人年事件率比</option></select><small>RR 在论文里有时也缩写事件率比，务必核对定义。</small></label><div class="form-grid"><label class="field"><span id="baseline-label">基线累计死亡概率 / %</span><input id="baseline" type="number" min="0" step="0.1" value="5" inputmode="decimal"></label><label class="field" id="years-field">该概率对应的时间窗 / 年<input id="years" type="number" min="0.1" max="100" step="0.1" value="10" inputmode="decimal"></label></div><div class="form-grid"><label class="field">效应量点估计<input id="effect" type="number" min="0.001" step="0.01" value="0.8" inputmode="decimal"></label><div></div><label class="field">95% 区间下界<input id="low" type="number" min="0.001" step="0.01" value="0.7" inputmode="decimal"></label><label class="field">95% 区间上界<input id="high" type="number" min="0.001" step="0.01" value="0.9" inputmode="decimal"></label></div><p class="small" id="preset-note"></p><div class="sources" id="preset-source"></div><p id="calc-error" class="error" role="alert"></p></div><div><div class="panel result" id="risk-result" aria-live="polite"></div><div class="note">不能把步数、跑步、肌酸和药物的效应相加或相乘。它们可能作用于同一通路，研究人群、终点与时间也不同。</div></div></div><div class="panel"><div class="sectionline"><h2>中国饮食 · 论文里的长期情景</h2><span>Food4HealthyLife 2.0 / 2024</span></div><p>固定为论文中的 40 岁中国人群。以下展示原文表 2 的预设情景，<b>不是重新运行完整模型，也不代表你的个人预测</b>。</p><label class="field">论文人群<select id="diet-sex"><option value="female">女性（论文设定 1.65 m / 60 kg）</option><option value="male">男性（论文设定 1.75 m / 70 kg）</option></select></label><div class="columns" id="diet-output"></div><p class="small">与论文中的中国典型饮食相比，长期、持续改变整体饮食；区间为论文模型的不确定性区间。女性优化情景的摘要与表 2 下界不一致，此处明确采用表 2：5.0 年。没有把食物效应叠加成个人结果。</p><div class="sources">${sourceLink('f4')}</div></div>`;
function applyPreset(id){if(!presets[id])throw Error('无效预设');$('#preset').value=id;const p=presets[id];$('#effect-type').value=p.type;for(const key of ['baseline','effect','low','high','years'])$('#'+key).value=p[key];$('#preset-note').textContent=p.note;$('#preset-source').innerHTML=p.ref?sourceLink(p.ref):'';calc();}
function markCustom(){if($('#preset').value!=='custom'){$('#preset').value='custom';$('#preset-note').textContent='你已修改输入。结果按当前数值计算；请自行核对基线、人群、终点及时间一致性。';$('#preset-source').innerHTML=''}}
function calc(){const type=$('#effect-type').value;$('#baseline-label').textContent=type==='RATE'?'基线死亡数 / 1,000 人年':'基线累计死亡概率 / %';$('#years-field').hidden=type==='RATE';const val={type};for(const key of ['baseline','effect','low','high']){const el=$('#'+key);val[key]=el.value.trim()===''?NaN:Number(el.value)}try{const y=Number($('#years').value);if(type!=='RATE'&&(!Number.isFinite(y)||y<=0||y>100))throw Error('请填写大于 0 且不超过 100 年的时间窗。');const r=convert(val),unit=type==='RATE'?' / 1,000 人年':'%',abs=r.difference,relative=(1-val.effect)*100;$('#calc-error').textContent='';const scale=Math.max(val.baseline,r.result,1);$('#risk-result').innerHTML=`<span class="labelcaps" style="color:#b7d1da">情景换算 · ${type==='RATE'?'事件率':y+' 年累计概率'}</span><span class="big">${r.result.toFixed(2)}${type==='RATE'?'':'%'}</span><p>${type==='RATE'?'估算死亡数 / 1,000 人年':'给定假设下的估算死亡概率'}</p><p class="small">效应区间映射：${r.lower.toFixed(2)}–${r.upper.toFixed(2)}${unit}</p><div class="barrow"><span>基线 ${val.baseline.toFixed(2)}${unit}</span><div class="bar"><i class="baseline" style="width:${val.baseline/scale*100}%"></i></div><span>换算后 ${r.result.toFixed(2)}${unit}</span><div class="bar"><i style="width:${r.result/scale*100}%"></i></div></div><div class="rule"><p>${type==='HR'?'瞬时风险':type==='RATE'?'事件率':'累计风险'}相对${relative>=0?'降低':'增加'} <b>${Math.abs(relative).toFixed(1)}%</b></p><p>${type==='RATE'?'死亡率差':'绝对概率差'}：${abs>=0?'减少':'增加'} <b>${Math.abs(abs).toFixed(2)}${type==='RATE'?' / 1,000 人年':' 个百分点'}</b></p><p>${type==='RATE'?'每 1,000 人观察一年':'每 1,000 人在该时间窗内'}，估计${abs>=0?'少':'多'} ${Math.abs(r.per1000).toFixed(1)} 例死亡。</p></div><p class="small">${type==='HR'?'假设比例风险成立：p₁ = 1 − (1 − p₀)^HR。':type==='RR'?'p₁ = p₀ × RR；只适用于同一时间窗的累计风险比。':'率₁ = 率₀ × 事件率比；不由此推导累计死亡概率。'} 区间仅传播效应量区间；未计入基线误差、模型偏差和人群差异。</p><p class="small">没有估计“多活几年”，也不说明该关联一定具有因果性。</p>`;}catch(e){$('#calc-error').textContent=e.message;$('#risk-result').innerHTML='<h3>请检查输入</h3><p>修正左侧数值后，会重新显示换算结果。</p>'}}
$('#preset').onchange=e=>applyPreset(e.target.value);for(const id of ['effect-type','baseline','effect','low','high','years'])$('#'+id).addEventListener(id==='effect-type'?'change':'input',()=>{markCustom();calc()});
function dietUpdate(){const p=dietScenarios[$('#diet-sex').value];$('#diet-output').innerHTML=[['feasible','较容易实现的整体改变'],['optimized','模型中的优化饮食']].map(([k,t])=>`<div><span class="small">${t}</span><p class="compare-metric">+ ${p[k][0].toFixed(1)} 年</p><p class="small">不确定性区间 ${p[k][1].toFixed(1)}–${p[k][2].toFixed(1)} 年</p></div>`).join('')};$('#diet-sex').onchange=dietUpdate;
$('#research').innerHTML=`<p class="eyebrow">新论文，要能改变一个决定</p><h1>论文雷达。</h1><p class="lede">查阅截至 2026 年 10 月 7 日的精选研究。不是全量系统综述，也未开启自动更新。</p><div class="note">本版的 alpha 判断：优先看低成本、可坚持、与你的起点匹配的改变。没有发现能让健康人稳定“套利寿命”的小圈子万能方案。</div>${updates.map(u=>`<article class="listrow"><span class="date">${u.date}</span><h3>${u.title}</h3><p>${u.text}</p><a href="${sources[u.ref].url}" target="_blank" rel="noopener">阅读原文</a><span class="small"> · ${sources[u.ref].journal}</span></article>`).join('')}<div class="panel"><h2>什么研究值得改变首页结论？</h2><p>先看是否研究了人、是否随机分组、实际终点是什么。再看效应大小和区间、基线风险、随访、绝对差、重复验证及不良反应。</p><p>只改变端粒、血糖或某种生物年龄时，保留这个终点；不自动升级为降低死亡率。新论文不能仅因更新就替换更可靠的旧证据。</p></div>`;
$('#method').innerHTML=`<p class="eyebrow">精确到边界，也是一种精确</p><h1>模型如何选。</h1><p class="lede">保留 HENI 的直观性，把个人决策放到更适合的问题和数据上。</p><div class="panel"><h2>三层证据，三种输出</h2><div class="listrow"><span class="tag">01 / 饮食与长期寿命</span><h3>Food4HealthyLife 2.0 的生命表思路</h3><p>使用食物组摄入与死亡的剂量反应关系，结合中国的年龄、性别背景死亡率，比较长期饮食模式，再积分生存曲线求预期寿命差。它比“单次吃一份赚几分钟”更适合长期情景问题，但仍是模型推算。</p><p class="small">本版只引用表 2 中已发表的中国 40 岁情景。完整的个体食谱模型仍需整理可许可的剂量反应参数、中国死亡表、食物配方与摄入基线，独立复现并验证。</p>${sourceLink('f4')}</div><div class="listrow"><span class="tag">02 / 全因死亡</span><h3>用同一人群、同一时间窗换算绝对风险</h3><div class="formula">HR：p₁(T) = 1 − [1 − p₀(T)] ^ HR<br>RR：p₁(T) = p₀(T) × RR<br>事件率比：rate₁ = rate₀ × rate ratio</div><p>第一式要求比例风险等条件；改变时间窗不能仅换个年份标签，必须重新取得对应的基线风险和适用效应。本工具不会根据年龄凭空生成基线。</p></div><div class="listrow"><span class="tag">03 / 身体功能与当下感受</span><h3>力量、睡眠、心情，也值得单独衡量</h3><p>肌酸带来的训练表现、户外活动的体验，不需要先证明延寿才有价值。它们也不能伪装成死亡率或寿命数据。</p></div></div><div class="panel"><h2>HENI 到底算了什么？</h2><p>2021 年原研究把美国饮食中的食物与疾病负担联系起来，得到每份食物关联的健康生命分钟。基础单位是 DALY（伤残调整寿命年），同时涉及早死和带病生活，<b>不是给你个人的寿命账户充值</b>。</p><div class="formula">1 DALY = 365 × 24 × 60 = 525,600 健康生命分钟（采用 365 日制）</div><p>单位能换算，概念不能偷换。相同 DALY 差可能来自完全不同的伤残和死亡组合，因此不能唯一反推全因死亡率，更不能把 HENI 分钟直接换成多活的钟表时间。</p><div class="sources">${sourceLink('heni')}</div></div><div class="panel"><h2>中国版本真正需要补的四件事</h2><ol><li><b>拆配方：</b>把杂粮饭、豆腐菜、水果捞、火锅和腊肉拆到实际食材；统一干重、生熟重、含水量和可食部。</li><li><b>定义替代：</b>增加豆类替代什么？改变总能量，还是等能量替换？避免把“加一种健康食物”当无限增益。</li><li><b>本土校准：</b>接入中国基线饮食和年龄、性别死亡表，检查中国队列中的外部有效性。风险模型应处理起效延迟、剂量非线性和重叠效应。</li><li><b>诚实表达误差：</b>对参数做抽样和敏感性分析；仅呈现可支持的范围。健康寿命还需疾病发生、伤残权重和状态转移，不能拿预期寿命直接冒充。</li></ol><p class="small">第一版已实现证据查阅、配方组成、HR / RR / 事件率比换算及论文情景展示；尚未完成上述完整本土模型校准。食物组解释不等于经验证的中国版 HENI 数据库。</p></div><div class="panel"><h2>“药食同源”放在哪里？</h2><p>食物、补剂、药物可以放进同一套证据卡，但食用历史或类别名称本身不能证明全因死亡获益。药物必须先匹配疾病与适应人群；一个药在心衰患者中有效，不等于适合健康人抗衰。</p></div><div class="panel"><h2>Ellen Bass 的那首诗</h2><p>你想起的是 <i>Relax</i>，收录于 <i>Like a Beggar</i>（2014）。提到维生素和普拉提的句子，随后写的是丢钥匙、掉头发和记忆衰退；你的转述抓住了它关于无常的主题。</p><p>我更愿意从中取出一个产品原则：努力改善可改变的风险，同时保留吃水果、晒好天气、运动时的快乐，不把每一分钟都变成考核。</p><div class="sources">${sourceLink('poem')}</div></div><details><summary>来源清单与阅读边界（${Object.keys(sources).length} 项）</summary><p class="small">来源包含原始研究、汇总研究、指南和文学出处。可访问正文时核查正文；部分条目依赖出版方或 PubMed 摘要。不是注册的系统综述，未覆盖所有新研究、勘误或撤稿。卡片中的优先级与实践建议是综合判断。</p><div class="sources">${Object.keys(sources).map(sourceLink).join('')}</div></details><details><summary>iPhone 使用与数据</summary><p>用 Safari 打开，点“分享 → 添加到主屏幕”。这是移动网页版，不是 App Store 原生应用。未接入 Apple 健康、相机食物识别或通知，也没有自动读论文。</p><p>搜索和计算在当前浏览器完成，本站不保存健康档案。托管服务负责登录和正常访问日志。计算输入刷新后重置；私有访问仍需账号验证。</p></details>`;
renderCards();applyPreset('example');dietUpdate();if(location.hash)page(location.hash.slice(1));
const mc=document.modelContext;
if(mc?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});Promise.resolve(mc.registerTool({name:'search_health_evidence',title:'查找健康证据',description:'筛选并显示本站已有的饮食、运动、补剂或药物证据；不诊断、不制定处方。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>120||Object.keys(input).some(k=>k!=='query'))throw Error('请输入不超过 120 字的查询');filter='全部';$('#search').value=input.query;syncFilters();renderCards();page('explore');return{shown:$('#result-count').textContent,query:input.query}}},{signal:life.signal})).catch(()=>{});}
